import{_ as l,a0 as p,w as o,s as d,I as t,x as a,a1 as n,A as i,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 中改變主機名的 4 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中改變主機名的 4 種方法 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中改變主機名的 4 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中改變主機名的 4 種方法 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190215 4 Methods To Change The HostName In Linux","title":"Linux 中改變主機名的 4 種方法","tag":"201903","desc":""},"relativePath":"201903/20190215 4 Methods To Change The HostName In Linux.md","filePath":"[post].md"}'),c={name:"201903/20190215 4 Methods To Change The HostName In Linux.md"};function g(r,s,u,k,m,b){const e=p("Link");return o(),d("div",null,[s[18]||(s[18]=t("h1",{id:"linux-中改變主機名的-4-種方法",tabindex:"-1"},[a("Linux 中改變主機名的 4 種方法 "),t("a",{class:"header-anchor",href:"#linux-中改變主機名的-4-種方法","aria-label":"Permalink to “Linux 中改變主機名的 4 種方法”"},"​")],-1)),t("p",null,[s[1]||(s[1]=a("昨天我們已經在我們的網站中寫過",-1)),n(e,{href:"https://www.2daygeek.com/linux-change-set-hostname/"},{default:i(()=>[...s[0]||(s[0]=[a("如何在 Linux 中修改主機名的文章",-1)])]),_:1}),s[2]||(s[2]=a("。今天，我們將向你展示使用不同的方法來修改主機名。你可以從中選取最適合你的方法。",-1))]),s[19]||(s[19]=h(`<p>使用 <code>systemd</code> 的系統自帶一個名為 <code>hostnamectl</code> 的好用工具，它可以使我們能夠輕易地管理系統的主機名。</p><p>當你使用這個原生命令時，它可以立刻改變主機名而無需重啓來生效。</p><p>但假如你通過手動修改某個配置文件來更改主機名，那麼就可能需要經過重啓來生效。</p><p>在這篇文章中，我們將展示在使用 <code>systemd</code> 的系統中改變主機名的 4 種方法。</p><p><code>hostnamectl</code> 命令允許在 Linux 中設置三類主機名，它們的細節如下：</p><ul><li><strong>靜態：</strong> 這是靜態主機名，由系統管理員添加。</li><li><strong>瞬時/動態：</strong> 這個由 DHCP 或者 DNS 服務器在運行時賦予。</li><li><strong>易讀形式：</strong> 它可以由系統管理員賦予。這個是自由形式的主機名，以一種易讀形式來表示服務器，例如 “JBOSS UAT Server” 這樣的名字。</li></ul><p>這些都可以使用下面 4 種方法來設置。</p><ul><li><code>hostnamectl</code> 命令：控制系統主機名。</li><li><code>nmcli</code> 命令：是一個控制 NetworkManager 的命令列工具。</li><li><code>nmtui</code> 命令：是一個控制 NetworkManager 的文本用户界面。</li><li><code>/etc/hostname</code> 文件：這個文件中包含系統的靜態主機名。</li></ul><h3 id="方法-1-在-linux-中使用-hostnamectl-來改變主機名" tabindex="-1">方法 1：在 Linux 中使用 hostnamectl 來改變主機名 <a class="header-anchor" href="#方法-1-在-linux-中使用-hostnamectl-來改變主機名" aria-label="Permalink to “方法 1：在 Linux 中使用 hostnamectl 來改變主機名”">​</a></h3><p><code>hostnamectl</code> 可被用來查詢和改變系統的主機名，以及相關設定。只需運行 <code>hostnamectl</code> 便可以查看系統的主機名了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl</span></span></code></pre></div><p>或者使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl status</span></span>
<span class="line"><span>   Static hostname: daygeek-Y700</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><p>假如你想改變主機名，可以使用下面的命令格式：</p><p>語法格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl set-hostname [YOUR NEW HOSTNAME]</span></span></code></pre></div><p>使用下面的命令來使用 <code>hostnamectl</code> 更改主機名。在這個例子中，我將把主機名從 <code>daygeek-Y700</code> 改為 <code>magi-laptop</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl set-hostname magi-laptop</span></span></code></pre></div><p>你可以使用下面的命令來查看更新後的主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl</span></span>
<span class="line"><span>   Static hostname: magi-laptop</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><h3 id="方法-2-在-linux-中使用-nmcli-命令來更改主機名" tabindex="-1">方法 2：在 Linux 中使用 nmcli 命令來更改主機名 <a class="header-anchor" href="#方法-2-在-linux-中使用-nmcli-命令來更改主機名" aria-label="Permalink to “方法 2：在 Linux 中使用 nmcli 命令來更改主機名”">​</a></h3><p><code>nmcli</code> 是一個命令列工具，旨在控制 NetworkManager 並報告網絡狀態。</p><p><code>nmcli</code> 被用來創建、展示、編輯、刪除、激活和註銷網絡連接，同時還可以用來控制和展示網絡設備的狀態。另外，它也允許我們更改主機名。</p><p>使用下面的命令來利用 <code>nmcli</code> 查看當前的主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmcli general hostname</span></span>
<span class="line"><span>daygeek-Y700</span></span></code></pre></div><p>語法格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmcli general hostname [YOUR NEW HOSTNAME]</span></span></code></pre></div><p>使用下面的命令來藉助 <code>nmcli</code> 命令可以更改主機名。在這個例子中，我將把主機名從 <code>daygeek-Y700</code> 變成 <code>magi-laptop</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmcli general hostname magi-laptop</span></span></code></pre></div><p>它可以在不重啓下設備的情況下生效，但為了安全目的，只需要重啓 <code>systemd-hostnamed</code> 服務來使得更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart systemd-hostnamed</span></span></code></pre></div><p>再次運行相同的 <code>nmcli</code> 命令來檢查更改後的主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmcli general hostname</span></span>
<span class="line"><span>magi-laptop</span></span></code></pre></div><h3 id="方法-3-在-linux-中使用-nmtui-來更改主機名" tabindex="-1">方法 3：在 Linux 中使用 nmtui 來更改主機名 <a class="header-anchor" href="#方法-3-在-linux-中使用-nmtui-來更改主機名" aria-label="Permalink to “方法 3：在 Linux 中使用 nmtui 來更改主機名”">​</a></h3><p><code>nmtui</code> 是一個基於 <code>curses</code> 庫的 TUI 應用，被用來和 NetworkManager 交互。當啓動 <code>nmtui</code> 後，如果沒有指定 <code>nmtui</code> 的第一個命令列參數，它將提醒用户選擇執行某項活動。</p><p>在終端中運行下面的命令來開啓文本用户界面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nmtui</span></span></code></pre></div><p>使用向下箭頭按鍵來選擇 “Set system hostname” 這個選項，然後敲擊回車鍵。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-1.png" alt=""></p><p>下面的截圖展示的是原來的主機名。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-2.png" alt=""></p><p>我們需要做的就是刪除原來的主機名，再輸入新的主機名，然後選中 “OK” 敲擊回車確認就可以了。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-3.png" alt=""></p><p>然後它將在屏幕中向你展示更新後的主機名，再次選中 “OK” 敲擊回車確認就完成更改了。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-4.png" alt=""></p><p>最後，選中 “Quit” 按鈕來從 <code>nmtui</code> 終端界面離開。</p><p><img src="https://www.2daygeek.com/wp-content/uploads/2019/02/four-methods-to-change-the-hostname-in-linux-5.png" alt=""></p><p>它可以在不重啓設備的情況下生效，但為了安全目的，需要重啓 <code>systemd-hostnamed</code> 服務來使得更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart systemd-hostnamed</span></span></code></pre></div><p>你可以運行下面的命令來查看更新後的主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl</span></span>
<span class="line"><span>   Static hostname: daygeek-Y700</span></span>
<span class="line"><span>         Icon name: computer-laptop</span></span>
<span class="line"><span>           Chassis: laptop</span></span>
<span class="line"><span>        Machine ID: 31bdeb7b83230a2025d43547368d75bc</span></span>
<span class="line"><span>           Boot ID: 267f264c448f000ea5aed47263c6de7f</span></span>
<span class="line"><span>  Operating System: Manjaro Linux</span></span>
<span class="line"><span>            Kernel: Linux 4.19.20-1-MANJARO</span></span>
<span class="line"><span>      Architecture: x86-64</span></span></code></pre></div><h3 id="方法-4-在-linux-中使用-etc-hostname-來更改主機名" tabindex="-1">方法 4：在 Linux 中使用 /etc/hostname 來更改主機名 <a class="header-anchor" href="#方法-4-在-linux-中使用-etc-hostname-來更改主機名" aria-label="Permalink to “方法 4：在 Linux 中使用 /etc/hostname 來更改主機名”">​</a></h3><p>除了上面的方法外，我們還可以通過修改 <code>/etc/hostname</code> 文件來達到修改主機名的目的。但這個方法需要服務器重啓才能生效。</p><p>使用下面的命令來檢查 <code>/etc/hostname</code> 文件以查看當前的主機名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>daygeek-Y700</span></span></code></pre></div><p>要改變主機名，只需覆寫這個文件就行了，因為這個文件只包含主機名這一項內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo echo &quot;magi-daygeek&quot; &gt; /etc/hostname</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>magi-daygeek</span></span></code></pre></div><p>然後使用下面的命令重啓系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo init 6</span></span></code></pre></div><p>最後查看 <code>/etc/hostname</code> 文件的內容來驗證主機名是否被更改了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/hostname</span></span>
<span class="line"><span>magi-daygeek</span></span></code></pre></div><hr>`,62)),t("p",null,[s[4]||(s[4]=a("via: ",-1)),n(e,{href:"https://www.2daygeek.com/four-methods-to-change-the-hostname-in-linux/"},{default:i(()=>[...s[3]||(s[3]=[a("https://www.2daygeek.com/four-methods-to-change-the-hostname-in-linux/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=a("作者：",-1)),n(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:i(()=>[...s[5]||(s[5]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),n(e,{href:"https://github.com/FSSlc"},{default:i(()=>[...s[7]||(s[7]=[a("FSSlc",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=l(c,[["render",g]]);export{y as __pageData,C as default};
